--
-- Name: clearalldata(); Type: FUNCTION; Schema: dbvpg; Owner: postgres
--

CREATE FUNCTION dbvpg.clearalldata() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
_row record;
_tempS text;
BEGIN

delete from dbvpg.alldata where taxon_name is null;

update dbvpg.alldata set collected_by = null where collected_by = 'unknown';

Alter table dbvpg.alldata add column accessionnumber text;      
update dbvpg.alldata set accessionnumber = 'DBVPG' || ' ' || accession_number;
Alter table dbvpg.alldata drop column accession_number;

Alter table dbvpg.alldata add column genus text;      
Alter table dbvpg.alldata add column species text;      
update dbvpg.alldata set genus = split_part(taxon_name,' ',1);            
update dbvpg.alldata set species = split_part(taxon_name,' ',2);            
Alter table dbvpg.alldata drop column taxon_name;      

Alter table dbvpg.alldata add column organismtype text;      
update dbvpg.alldata set organismtype = 'Yeasts';
update dbvpg.alldata set organismtype = 'Algae' where genus = 'Prototheca';

update dbvpg.alldata set gmo = null where ((gmo not ilike 'yes') and (gmo not ilike 'no'));
update dbvpg.alldata set gmo = 'Yes' where gmo ilike 'yes';
update dbvpg.alldata set gmo = 'No' where gmo ilike 'no';

alter table dbvpg.alldata rename column year_of_collection to collectionDate;

alter table dbvpg.alldata rename column date_of_deposit to depositDate;
update dbvpg.alldata set depositDate = null where depositdate = 'unknown';
update dbvpg.alldata set depositDate = replace(depositDate,'/','-');

alter table dbvpg.alldata rename column year_of_isolation to isolationDate;

update dbvpg.alldata set restrictions_on_use = upper(restrictions_on_use);



create table dbvpg.people as select * from susmirri.people;
select row_number() OVER (Order by P), 'P' || row_number() OVER (Order by P), P 
from (
	select distinct collected_by P from dbvpg.alldata  where collected_by is not null	
) T;

alter table dbvpg.allData add column collector text;
update dbvpg.allData set collector = id from dbvpg.people where fname = collected_by;

alter table dbvpg.allData drop column collected_by;


--select distinct collected_by from dbvpg.alldata where restrictions_on_use not in (select restrictions from userestrictions)

return 1;
end; 
$$;


ALTER FUNCTION dbvpg.clearalldata() OWNER TO postgres;

--
-- Name: initializealldata(); Type: FUNCTION; Schema: dbvpg; Owner: postgres
--

CREATE FUNCTION dbvpg.initializealldata() RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
BEGIN

delete from dbvpg.dbv_lieviti_1 where (accession_number,idlievito) in
(select accession_number, max(idlievito)
from dbvpg.dbv_lieviti_1
group by accession_number
having count(*) > 1);

delete from dbvpg.dbv_lieviti_2 where (accession_number,idlievito) in
(select accession_number, max(idlievito)
from dbvpg.dbv_lieviti_2
group by accession_number
having count(*) > 1);

delete from dbvpg.dbv_lieviti_3 where (accession_number,idlievito) in
(select accession_number, max(idlievito)
from dbvpg.dbv_lieviti_3
group by accession_number
having count(*) > 1);

delete from dbvpg.dbv_lieviti_4 where (accession_number,idlievito) in
(select accession_number, max(idlievito)
from dbvpg.dbv_lieviti_4
group by accession_number
having count(*) > 1);

delete from dbvpg.dbv_lieviti_5 where (accession_number,idlievito) in
(select accession_number, max(idlievito)
from dbvpg.dbv_lieviti_5
group by accession_number
having count(*) > 1);

delete from dbvpg.dbv_lieviti_6 where (accession_number,idlievito) in
(select accession_number, max(idlievito)
from dbvpg.dbv_lieviti_6
group by accession_number
having count(*) > 1);


ALTER TABLE dbvpg.dbv_lieviti_1 DROP COLUMN idlievito;
ALTER TABLE dbvpg.dbv_lieviti_2 DROP COLUMN idlievito;
ALTER TABLE dbvpg.dbv_lieviti_3 DROP COLUMN idlievito;
ALTER TABLE dbvpg.dbv_lieviti_4 DROP COLUMN idlievito;
ALTER TABLE dbvpg.dbv_lieviti_5 DROP COLUMN idlievito;
ALTER TABLE dbvpg.dbv_lieviti_6 DROP COLUMN idlievito;

create table dbvpg.alldata as select * 
from dbvpg.dbv_lieviti_1 
natural join dbvpg.dbv_lieviti_2 
natural join dbvpg.dbv_lieviti_3 
natural join dbvpg.dbv_lieviti_4 
natural join dbvpg.dbv_lieviti_5 
natural join dbvpg.dbv_lieviti_6;



return 1;
end; 
$$;


ALTER FUNCTION dbvpg.initializealldata() OWNER TO postgres;

--
-- Name: createtriggers(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.createtriggers() RETURNS boolean
    LANGUAGE plpgsql
    AS $$
begin

CREATE OR REPLACE TRIGGER HISTORY
AFTER INSERT OR UPDATE OR DELETE ON Strain
FOR EACH ROW
EXECUTE FUNCTION history(StrainID, hStrain);

CREATE OR REPLACE TRIGGER HISTORY
AFTER INSERT OR UPDATE OR DELETE ON Microorganism
FOR EACH ROW
EXECUTE FUNCTION history(Strain, hMicroorganism);

CREATE OR REPLACE TRIGGER HISTORY
AFTER INSERT OR UPDATE OR DELETE ON FormOfSupply
FOR EACH ROW
EXECUTE FUNCTION historyFormOfSupply();

return false;
end;
$$;


ALTER FUNCTION public.createtriggers() OWNER TO postgres;

--
-- Name: createviews(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.createviews() RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare
_tempS text;
begin

DROP VIEW IF EXISTS SyntheticStrain;
CREATE VIEW SyntheticStrain AS
select acronym collection, accessionnumber, acronym || ' ' || accessionnumber fullaccessionnumber,
	morganismtype organismtype, genus taxonname, strainid
from microorganism join strain on strain=strainid
	join collection on collection=collectionid
where species is null
UNION
select acronym collection, accessionnumber, acronym || ' ' || accessionnumber fullaccessionnumber,
	morganismtype organismtype, GENUS || ' ' || species SCIENTIFICNAME, strainid
from microorganism join strain on strain=strainid
join collection on collection=collectionid
where species is not null
UNION
select acronym collection, accessionnumber, acronym || ' ' || accessionnumber fullaccessionnumber,
	vorganismtype organismtype, scientificname, strainid
from virus join strain on strain=strainid
join collection on collection=collectionid;
--grant select on SyntheticStrain to susmirri;

DROP VIEW IF EXISTS DetailedStrain;
CREATE VIEW DetailedStrain AS
SELECT S.*,
C.acronym cacronym, confirmed, 
coalesce(M.morganismtype, v.vorganismtype) organismtype,
coalesce(mriskgroup,vriskgroup) riskgroup,
coalesce(meuquarantine,veuquarantine) euquarantine,
M.*,
ScientificName, inEva, InMirri, OtherNames,
IsolationHost, Name, Abbreviation, PropagationHost,
Cultivar,LyticCicle,PathotypeSerotypeType,
StorageConditions, SymptomatologyOnIsolationHost,
TransmissionBy, Contamination, InfectivityTested,
UR.restrictions, 
N.protocol nagoyaprotocol
FROM strain S 
JOIN Collection C on (S.collection = C.collectionID)
LEFT JOIN microorganism M ON S.strainid = M.Strain
LEFT JOIN Virus V ON S.strainid = V.Strain
LEFT JOIN UseRestrictions UR on S.userestrictions = UR.restrictionsID
LEFT JOIN NagoyaConditions N on S.nagoyaConditions = N.protocolID;
--GRANT select on DetailedStrain to susmirri;

CREATE OR REPLACE VIEW CollectedV AS
select strain, personid, acronym || ' ' || ccid as ccid, fname,lname, dept, institution, country, email
from person join collected on (personid = person)
join collection on collection=collectionid;

CREATE OR REPLACE VIEW DEPOSITEDV AS
select strain, personid, acronym || ' ' || ccid as ccid, fname,lname, dept, institution, country, email
from person join deposited on (personid = person)
join collection on collection=collectionid;

CREATE OR REPLACE VIEW ISOLATEDV AS
select strain, personid, acronym || ' ' || ccid as ccid, fname,lname, dept, institution, country, email
from person join isolated on (personid = person)
join collection on collection=collectionid;

CREATE OR REPLACE VIEW HStrainV AS
SELECT * FROM HStrain
UNION
SELECT * FROM HMICROORGANISM
UNION
SELECT * FROM HVIRUS;

CREATE OR REPLACE VIEW mediumv AS
select  mediumID, C.acronym cacronym, M.acronym macronym,  
	M.description mdescription, fulldescription 
from Medium M join Collection C on (Collection=CollectionID);

CREATE VIEW JPaperV AS
SELECT collection, c.acronym as cacronym, ccID, J.*
FROM jpaper J JOIN literature l ON (J.literature = L.literatureID)
JOIN collection c on (collectionid = collection);

FOR _tempS IN select table_name from information_schema.tables
		where table_schema = 'public'
		and (table_type = 'BASE TABLE'
		or table_type = 'VIEW') LOOP
	execute 'grant select on ' || _tempS ||' to susmirri';	
END LOOP;



return false;
end;
$$;


ALTER FUNCTION public.createviews() OWNER TO postgres;

