--
-- Name: history(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.history() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
	_opID bigint;
	_key text;
	_value text; 
	_newj json;
	_oldj json;
	_query text;
	_objID bigint;
	_loopj json;
BEGIN
	IF (TG_OP = 'INSERT') THEN 
		_newj = json_strip_nulls(row_to_json(NEW));
		_objID = _newj->>TG_ARGV[0];
		_query = 'INSERT INTO ' || TG_ARGV[1] || '(timeistant, opID, objID, opName) ' ||
		'VALUES($1, 1, $2, $3)';
		EXECUTE _query USING now(), _objID, TG_OP;	
	ELSIF (TG_OP = 'UPDATE') THEN
		_newj = json(row_to_json(NEW));
		_oldj = json(row_to_json(OLD));
		_objID = _newj->>TG_ARGV[0];
		FOR _key, _value IN SELECT * FROM json_each_text(_newj) LOOP
			_query = 'SELECT COALESCE(MAX(opid), 0) 
			FROM  ' || TG_ARGV[1] || ' ' ||
			'WHERE objID = $1 AND timeistant = now() ';
			EXECUTE _query using _objID INTO _opID;
			IF ((_newj->>_key <> _oldj->>_key) OR 
				((_newj->>_key is null) AND (_oldj->>_key is not null)) OR  
				((_newj->>_key is not null) AND (_oldj->>_key is null)))  THEN	
				_opID = _opID+1;
				_query = 'INSERT INTO ' || TG_ARGV[1] || '(timeistant, opID, objID, opName, attrname, newvalue, oldvalue) ' ||
				'VALUES($1, $2, $3,$4, $5,$6,$7)';
				EXECUTE _query USING now(), _opID, _objID,
				TG_OP, _key, _newj->>_key,_oldj->>_key;		
			END IF;
		END LOOP;
	ELSIF (TG_OP = 'DELETE') THEN
		_oldj = json_strip_nulls(row_to_json(OLD));
		FOR _key, _value IN SELECT * FROM json_each_text(_newj) LOOP
			_query = 'INSERT INTO ' || TG_ARGV[1] || '(timeistant, opID, objID, opName, attrname, oldvalue) ' ||
			'VALUES($1, 1, $2, $3, $4, $6)';
			EXECUTE _query USING now(), _objID,
			TG_OP, _key, _oldj->>_key;		
		END LOOP;
	END IF;
RETURN NULL;
END; 
$_$;


ALTER FUNCTION public.history() OWNER TO postgres;

--
-- Name: historyformofsupply(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.historyformofsupply() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	_opID bigint;
	_strain bigint;
	_newValue text[]; 
	_oldValue text[]; 
	_query text;
	_tempRow record;
BEGIN

IF ((TG_OP = 'INSERT') OR (TG_OP = 'UPDATE')) THEN 
	_strain = NEW.strain;	
ELSE 
	_strain = OLD.strain;
END IF;

select (ARRAY (
select supplymethod from formofsupply 
where strain = _strain
ORDER BY supplymethod)) into _newValue;

IF (TG_OP = 'INSERT')  THEN 
	select (ARRAY (
	select unnest(_newValue) s
	except
	select NEW.supplymethod
	order by s)) into _oldValue;
ELSEIF (TG_OP = 'UPDATE') THEN
	select (ARRAY (
	select unnest(_newValue) s
	except
	select NEW.supplymethod
	order by s)) into _oldValue;
	select (ARRAY (
	select unnest(_oldValue) s
	UNION
	select OLD.supplymethod
	order by s)) into _oldValue;
ELSE 
	select (ARRAY (
	select unnest(_newValue) s
	UNION
	select OLD.supplymethod
	order by s)) into _oldValue;
END IF;

SELECT COALESCE(MAX(opid), 0) INTO _opID
FROM  HSTRAIN
WHERE objID = _strain AND timeistant = now();

IF (_oldValue::text <> _newValue::text) THEN
VALUES(now(), _opID+1, _strain, 'UPDATE', 'SupplyMethod', _oldValue::text, _newValue::text);
END IF;

RETURN NULL;
END; 
$$;


ALTER FUNCTION public.historyformofsupply() OWNER TO postgres;

--
-- Name: is_mirridate(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_mirridate(s character varying) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
declare 
_l int;
_m int;
_y int;
begin

SELECT CHAR_LENGTH(s) - CHAR_LENGTH(REPLACE(s,'-','')) into _l;
IF (_L = 0) THEN
  _y = s::int;
  if (_y < 0) THEN RETURN FALSE; END IF;
  perform s::int;
  return true;
ELSEIF (_L=1) THEN   
  _m = split_part(s,'-',1)::int;
  _y = split_part(s,'-',2)::int;
  if (_y < 0) THEN RETURN FALSE; END IF;
  if (_m < 0) THEN RETURN FALSE; END IF;
  if (_m > 12) THEN RETURN FALSE; END IF;
ELSE
  if (char_length(split_part(s,'-',3)) <> 4) then return false; end if;
  PERFORM to_date(s,'dd-mm-yyyy');
END IF;
return true;
exception when others then
return false;
end;
$$;


ALTER FUNCTION public.is_mirridate(s character varying) OWNER TO postgres;

