    LANGUAGE plpgsql
    AS $$
DECLARE
	_literatureID bigint;
BEGIN
	VALUES(new.collection, new.ccID)
	RETURNING literatureID INTO _literatureID;
					   journal, year, volume, issue, 
					   firstpage, doi)
	VALUES (_literatureID,new.authors,new.title, 
					   new.journal, new.year, new.volume, new.issue, 
