--
-- Name: popolaliterature(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.popolaliterature(schemaname text, collectionname text, sourcetable text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
	_collectionID bigint;
	_newLiteratureID bigint;
	_tempRow record;
BEGIN

IF (sourceTable <> 'JPapers') THEN
	RAISE EXCEPTION '% UNKNOWN TABLE', $3;		
END IF;

SELECT collectionID INTO _collectionID FROM collection WHERE upper(acronym) = upper($2);

FOR _tempRow IN
	EXECUTE 'select * from '|| $1 || '.' || $3 LOOP
	VALUES(_collectionID,_tempRow.id)
	RETURNING literatureid INTO _newLiteratureID;
	
	IF (sourceTable = 'JPapers') THEN
								  volume, issue, firstpage, doi, pmid)
	VALUES (_newLiteratureID, _tempRow.authors, 
			_tempRow.title, _tempRow.journal, _tempRow.year::float::int, 
			_tempRow.volume, _tempRow.issue, _tempRow.firstpage, _tempRow.doi, _tempRow.pmid);	
	END IF;
END LOOP;


return 1;
end; 
$_$;


ALTER FUNCTION public.popolaliterature(schemaname text, collectionname text, sourcetable text) OWNER TO postgres;

--
-- Name: popolastrain(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.popolastrain(schemaname text, collectionname text, sourcetable text) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
DECLARE
	_tempI bigint;
	_collectionID bigint;
	_geoOriginID bigint;
	_newStrainID bigint;
	_strainClass text;	
	_tempS text;	
	tempRow record;
BEGIN

ALTER TABLE FormOfSupply DISABLE TRIGGER history;
SELECT collectionID INTO _collectionID FROM collection WHERE upper(acronym) = upper($2);

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN beforenagoyabool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set beforenagoyabool = true where beforenagoya ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set beforenagoyabool = false where beforenagoya ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN availablefordisbool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set availablefordisbool = true where availablefordis ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set availablefordisbool = false where availablefordis ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN GMOBOOL BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set GMOBOOL = true where GMO ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set GMOBOOL = false where GMO ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN euquarantinebool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set euquarantinebool = true where euquarantine ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set euquarantinebool = false where euquarantine ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN typestrainbool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set typestrainbool = true where typestrain ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set typestrainbool = false where typestrain ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN regccbool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set regccbool = true where registeredcollection ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set regccbool = false where registeredcollection ilike $1' USING 'No';

if ($3 ilike 'MicroOrganisms') then
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN dualusebool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set dualusebool = true where dualuse ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set dualusebool = false where dualuse ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN qpsbool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set qpsbool = true where qps ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set qpsbool = false where qps ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN axenicbool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set axenicbool = true where axenic ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set axenicbool = false where axenic ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN interspecifichybridbool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set interspecifichybridbool = true where interspecifichybrid ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set interspecifichybridbool = false where interspecifichybrid ilike $1' USING 'No';

ELSEif ($3 ilike 'viruses') then
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN inevabool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set inevabool = true where ineva  ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set inevabool = false where ineva ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN inmirribool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set inmirribool = true where inmirri ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set inmirribool = false where inmirri ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN contaminationbool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set contaminationbool = true where contamination ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set contaminationbool = false where contamination ilike $1' USING 'No';

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' ADD COLUMN infectivitytestedbool BOOLEAN';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set infectivitytestedbool = true where infectivitytested ilike $1' USING 'Yes';
EXECUTE 'UPDATE ' || $1 || '.' || $3 || ' set infectivitytestedbool = false where infectivitytested ilike $1' USING 'No';

end if;

FOR tempRow IN
	EXECUTE 'select * from '|| $1 || '.' || $3 LOOP
		_strainClass = null;
		IF (SELECT EXISTS (SELECT OrganismType FROM MOrganismType WHERE organismType = tempRow.organismType)) THEN
			_strainClass = 'MicroOrganism';
		ELSEIF (SELECT EXISTS (SELECT OrganismType FROM VOrganismType WHERE organismType = tempRow.organismType)) THEN
			_strainClass = 'Virus';
		END IF;		
		IF (_strainClass is null) THEN
			RAISE EXCEPTION 'UNKNOWN STRAINCLASS FOR % IN % ',tempRow.organismtype, tempRow.accessionnumber;	
		END IF;
		
	_geoOriginID = NULL;
	IF (tempRow.geoOrigin is not null) THEN
		SELECT localityID into _geoOriginID FROM Locality
		WHERE Collection = _collectionID AND ccID = tempRow.geoOrigin;
		IF (_geoOriginID IS NULL) THEN
			RAISE NOTICE 'IN % GEOORIGIN % NOT FOUND',tempRow.accessionnumber, tempRow.geoOrigin;
		END IF;
	END IF;
					   beforenagoya,availablefordis,nagoyaconditions,
					   gmo, gmoconstructioninfo, 
					   collectiondate,inclusiondate,isolationdate,depositdate,
					   commentontaxonomy, identificationtechnique, mutantinformation,
					   userestrictions,
					   typeStrain,registeredcollection,pathogenicity,
					   otherdenominations,otherccnumbers,remarks,geoOrigin)
	VALUES(_collectionID,
		   split_part(tempRow.accessionnumber, ' ', 2),
		   temprow.beforenagoyabool,temprow.availablefordisbool,tempRow.nagoyaConditions::float::int,
		   tempRow.gmobool, tempRow.gmoconstructioninfo, 
		   tempRow.collectiondate,Temprow.inclusiondate,tempRow.isolationdate,tempRow.depositdate,
		   temprow.commentontaxonomy,temprow.identificationtechnique,temprow.mutantinformation,
		   tempRow.useRestrictions::float::int,
		   tempRow.typeStrainBool,tempRow.regCCbool,temprow.pathogenicity,
		   tempRow.otherdenomination,temprow.otherccnumbers,tempRow.remarks,
		   _geoOriginID)
	RETURNING strainid INTO _newStrainID;
	FOR _tempS IN SELECT unnest(string_to_array(temprow.formofsupply,';')) LOOP
		IF EXISTS (select * from supplymethod where supplymethod = TRIM(BOTH FROM _tempS)) THEN
			values(_newStrainID, TRIM(BOTH FROM _tempS));
		ELSE
			RAISE NOTICE 'IN SUPPLYMETHOD % NOT FOUND', _tempS;		
		END IF;
	END LOOP;
	FOR _tempS in select unnest(string_to_array(temprow.isolator,';')) LOOP
		select selectPerson(_collectionID,_tempS) into _tempI;
		if (_tempI is null) THEN
			RAISE NOTICE 'IN % ISOLATOR % NOT FOUND',tempRow.accessionnumber, _tempS;
		end if;
		values(_newStrainID, _tempI);
	end LOOP;
	for _tempS in select unnest(string_to_array(temprow.collector,';')) LOOP
		select selectPerson(_collectionID,_tempS) into _tempI;
		if (_tempI is null) THEN
			RAISE NOTICE 'COLLECTOR ERROR: % %',_tempS, tempRow.collector;
		end if;
		values(_newStrainID, _tempI);
	end LOOP;	
	for _tempS in select unnest(string_to_array(temprow.depositor,';')) LOOP
		select selectPerson(_collectionID,_tempS) into _tempI;
		if (_tempI is null) THEN
			RAISE NOTICE 'IN % DEPOSITOR % NOT FOUND',tempRow.accessionnumber, _tempS;
		end if;
		if (_tempI is not null) THEN
			values(_newStrainID, _tempI);
		end if;
	end LOOP;	
	for _tempS in select unnest(string_to_array(temprow.literature,';')) LOOP
		select selectLiterature(_collectionID,_tempS) into _tempI;
		if (_tempI is null) THEN
			RAISE NOTICE 'IN % LITERATURE % NOT FOUND',tempRow.accessionnumber, _tempS;
		end if;
		if (_tempI is not null) THEN
			values(_newStrainID, _tempI);
		end if;
	end LOOP;	
	for _tempS in select unnest(string_to_array(temprow.sequenceliterature,';')) LOOP
		select selectLiterature(_collectionID,_tempS) into _tempI;
		if (_tempI is null) THEN
			RAISE NOTICE 'IN % SEQUENCELITERATURE % NOT FOUND',tempRow.accessionnumber, _tempS;
		end if;
		if (_tempI is not null) THEN
			values(_newStrainID, _tempI);
		end if;
	end LOOP;	
	for _tempS in select unnest(string_to_array(temprow.links,';')) LOOP
		select selectLink(_collectionID,_tempS) into _tempI;
		if (_tempI is null) THEN
			RAISE NOTICE 'IN % LINK % NOT FOUND',tempRow.accessionnumber, _tempS;
		end if;
		if (_tempI is not null) THEN
			values(_newStrainID, _tempI);
		end if;
	end LOOP;	
	
		
	IF (_strainClass = 'MicroOrganism') THEN
		PERFORM storeMicroOrganism(tempRow,_collectionID, _newStrainID);	
	ELSEIF (_strainClass = 'Virus') THEN
		PERFORM storeVirus(tempRow,_collectionID, _newStrainID);	
	END IF;
END LOOP;

EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN beforenagoyabool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN availablefordisbool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN GMOBOOL';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN euquarantinebool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN typestrainbool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN regccbool';

if ($3 ilike 'MicroOrganisms') then
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN IF EXISTS dualusebool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN IF EXISTS qpsbool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN IF EXISTS axenicbool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN IF EXISTS interspecifichybridbool';
ELSEif ($3 ilike 'viruses') then
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN IF EXISTS inevabool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN IF EXISTS inmirribool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN IF EXISTS contaminationbool';
EXECUTE 'ALTER TABLE ' || $1 || '.' || $3 || ' DROP COLUMN IF EXISTS infectivitytestedbool';
end if;

ALTER TABLE FormOfSupply ENABLE TRIGGER history;

return 1;
end; 
$_$;


