--
-- Name: selectlink(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.selectlink(collectionid bigint, temps text) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
declare 
_tempS text;
_tempI bigint;
begin
_tempS = trim(BOTH FROM tempS);
if (_tempS='') then return null; end if;
select linkID from LINK into _tempI
where Collection= $1 and ccID = _tempS;
return _tempI;
end;
$_$;


