--

CREATE FUNCTION public.selectperson(collectionid bigint, temps text) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
declare 
_tempS text;
_tempI bigint;
begin
_tempS = trim(BOTH FROM tempS);
if (_tempS='') then return null; end if;
select personID from PERSON into _tempI
where Collection= $1 and ccID = _tempS;
if (_tempI is null) then
select personID from PERSON into _tempI
where Collection= $1 and fName = _tempS;
end if;
return _tempI;
end;
$_$;


