--
-- Name: storemicroorganism(record, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storemicroorganism(temprow record, collectionid bigint, _newstrainid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	_geoOriginID bigint;
	_tempS text;
	_tempI bigint;
BEGIN
							  morganismType, genus, species,							  
							  recommendedtemperature,testedTGMin,testedTGMax,							  
							  dualUse,sexualState, 							  
							  substrate,mtafile,prodOfMetabolites,
							  mEuQuarantine, isolationHabitat, status,
							  infrasubspecificnames, qps, axenic,
							  genotype, mRiskGroup,historyofdeposit, enzymeproduction,
							  applications, plasmids, plasmidscollectionsfields, ploidy, interspecifichybrid
							 )
	values(_newStrainID,
		   tempRow.organismType,tempRow.genus,tempRow.species,		   
		   tempRow.recommendedtempgrowth::float::int, 
		   split_part(temprow.TestedTempGrowthRange,';',1)::int,
		   split_part(temprow.TestedTempGrowthRange,';',2)::int,			
		   tempRow.dualUseBool, tempRow.sexualState,
		   temprow.substrate,temprow.mtafile, tempRow.productionofmetabolites,
		   temprow.euquarantinebool, tempRow.isolationHabitat,temprow.status,
		   tempRow.infrasubspecificnames,temprow.qpsbool, temprow.axenicbool,
		   temprow.genotype, temprow.riskgroup::float::int,
		   temprow.historyofdeposit, temprow.enzymeproduction, temprow.applications,
		   temprow.plasmids, temprow.plasmidscollectionsfields, temprow.ploidy,
		   temprow.interspecifichybridbool
		  );
	
	
	for _tempS in select unnest(string_to_array(temprow.ontobiotopeTerms,';')) LOOP
		_tempI = null;
		select ontobiotopeID into _tempI from ontobiotope
		where Collection=  collectionID   and acronym = _tempS;
		if (_tempI is not null) THEN
			values(_newStrainID, _tempI);
		else
			RAISE NOTICE 'ontobiotope error % %',_tempS, tempRow.accessionnumber;
		end if;
	END LOOP;
	
	for _tempS in select unnest(string_to_array(temprow.recommendedmediumgrowth,';')) LOOP
		_tempI = null;
		_tempS = trim(BOTH FROM _tempS);
		execute 'select mediumID from MEDIUM 
				where Collection=' || collectionID || ' and acronym = ''' || _tempS || ''''
				into _tempI;
		if (_tempI is not null) THEN
			values(_newStrainID, _tempI);
		else
			RAISE NOTICE 'GrowthMedium error % %',_tempS, tempRow.accessionnumber;
		end if;
	end LOOP;
	RAISE NOTICE 'ABSFiles for storemicroorganism to be done';
	
	
return 1;
end; 
$$;


ALTER FUNCTION public.storemicroorganism(temprow record, collectionid bigint, _newstrainid bigint) OWNER TO postgres;

--
-- Name: storevirus(record, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.storevirus(temprow record, collectionid bigint, _newstrainid bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
	_locationID bigint;
	_geoOriginID bigint;
	_tempI bigint;
	_tempS text;
BEGIN

					  inEVA,inMIRRI,
					  vEUQuarantine, vRiskGroup,
					  otherNames, isolationhost,
					  name,abbreviation,
					  propagationHost,cultivar,lyticcicle,PathotypeSerotypeType,
					  storageConditions,SymptomatologyOnIsolationHost,transmissionby,
					  contamination, infectivitytested)
	values(_newStrainID,temprow.organismtype, temprow.scientificname,
		   temprow.inEVAbool, temprow.inMIRRIbool,
		   tempRow.euquarantinebool, temprow.riskgroup::int,
		   temprow.othervirusnames,temprow.isolationhost,
		   temprow.name, temprow.abbreviation,
		   temprow.propagationhost, temprow.cultivar,temprow.lyticcicle,temprow.PathotypeSerotypeType,
		   temprow.storageconditions,temprow.SymptomatologyOnIsolationHost, temprow.transmissionby,
		   temprow.contaminationbool, temprow.infectivitytestedbool);
return 1;
end;
$$;


ALTER FUNCTION public.storevirus(temprow record, collectionid bigint, _newstrainid bigint) OWNER TO postgres;

