    depositdate text,
    otherdenominations text,
    typestrain boolean,
    inclusiondate text,
    remarks text,
    pathogenicity text,
    beforenagoya boolean,
    availablefordis boolean,
    otherccnumbers text,
    commentontaxonomy text,
    mutantinformation text,
    userestrictions integer,
    nagoyaconditions integer,
    geoorigin bigint,
    CONSTRAINT pp1 CHECK (((gmo = true) OR (gmoconstructioninfo IS NULL))),
    CONSTRAINT strain_collectiondate_check CHECK (public.is_mirridate((collectiondate)::character varying)),
    CONSTRAINT strain_depositdate_check CHECK (public.is_mirridate((depositdate)::character varying)),
    CONSTRAINT strain_inclusiondate_check CHECK (public.is_mirridate((inclusiondate)::character varying)),
    CONSTRAINT strain_isolationdate_check CHECK (public.is_mirridate((isolationdate)::character varying))
);


