--
-- Name: detailedstrain; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.detailedstrain AS
 SELECT s.strainid,
    s.collection,
    s.accessionnumber,
    s.gmo,
    s.gmoconstructioninfo,
    s.registeredcollection,
    s.collectiondate,
    s.isolationdate,
    s.identificationtechnique,
    s.depositdate,
    s.otherdenominations,
    s.typestrain,
    s.inclusiondate,
    s.remarks,
    s.pathogenicity,
    s.beforenagoya,
    s.availablefordis,
    s.otherccnumbers,
    s.commentontaxonomy,
    s.mutantinformation,
    s.userestrictions,
    s.nagoyaconditions,
    s.geoorigin,
    c.acronym AS cacronym,
    c.confirmed,
    COALESCE(m.morganismtype, v.vorganismtype) AS organismtype,
    COALESCE(m.mriskgroup, v.vriskgroup) AS riskgroup,
    COALESCE(m.meuquarantine, v.veuquarantine) AS euquarantine,
    m.strain,
    m.recommendedtemperature,
    m.dualuse,
    m.substrate,
    m.testedtgmin,
    m.testedtgmax,
    m.morganismtype,
    m.sexualstate,
    m.mtafile,
    m.prodofmetabolites,
    m.genus,
    m.species,
    m.meuquarantine,
    m.isolationhabitat,
    m.status,
    m.infrasubspecificnames,
    m.qps,
    m.axenic,
    m.genotype,
    m.mriskgroup,
    m.historyofdeposit,
    m.enzymeproduction,
    m.applications,
    m.plasmids,
    m.plasmidscollectionsfields,
    m.ploidy,
    m.interspecifichybrid,
    v.scientificname,
    v.ineva,
    v.inmirri,
    v.othernames,
    v.isolationhost,
    v.name,
    v.abbreviation,
    v.propagationhost,
    v.cultivar,
    v.lyticcicle,
    v.pathotypeserotypetype,
    v.storageconditions,
    v.symptomatologyonisolationhost,
    v.transmissionby,
    v.contamination,
    v.infectivitytested,
    ur.restrictions,
    n.protocol AS nagoyaprotocol
   FROM (((((public.strain s
     JOIN public.collection c ON ((s.collection = c.collectionid)))
     LEFT JOIN public.microorganism m ON ((s.strainid = m.strain)))
     LEFT JOIN public.virus v ON ((s.strainid = v.strain)))
     LEFT JOIN public.userestrictions ur ON ((s.userestrictions = ur.restrictionsid)))
     LEFT JOIN public.nagoyaconditions n ON ((s.nagoyaconditions = n.protocolid)));


ALTER TABLE public.detailedstrain OWNER TO postgres;

