--
-- Name: syntheticstrain; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.syntheticstrain AS
 SELECT collection.acronym AS collection,
    strain.accessionnumber,
    ((collection.acronym || ' '::text) || strain.accessionnumber) AS fullaccessionnumber,
    microorganism.morganismtype AS organismtype,
    microorganism.genus AS taxonname,
    strain.strainid
   FROM ((public.microorganism
     JOIN public.strain ON ((microorganism.strain = strain.strainid)))
     JOIN public.collection ON ((strain.collection = collection.collectionid)))
  WHERE (microorganism.species IS NULL)
UNION
 SELECT collection.acronym AS collection,
    strain.accessionnumber,
    ((collection.acronym || ' '::text) || strain.accessionnumber) AS fullaccessionnumber,
    microorganism.morganismtype AS organismtype,
    ((microorganism.genus || ' '::text) || microorganism.species) AS taxonname,
    strain.strainid
   FROM ((public.microorganism
     JOIN public.strain ON ((microorganism.strain = strain.strainid)))
     JOIN public.collection ON ((strain.collection = collection.collectionid)))
  WHERE (microorganism.species IS NOT NULL)
UNION
 SELECT collection.acronym AS collection,
    strain.accessionnumber,
    ((collection.acronym || ' '::text) || strain.accessionnumber) AS fullaccessionnumber,
    virus.vorganismtype AS organismtype,
    virus.scientificname AS taxonname,
    strain.strainid
   FROM ((public.virus
     JOIN public.strain ON ((virus.strain = strain.strainid)))
     JOIN public.collection ON ((strain.collection = collection.collectionid)));


ALTER TABLE public.syntheticstrain OWNER TO postgres;

